int a[5] = {10, 20, 30, 40, 50};
int *p = a;                    /* same as &a[0] */
p++;                           /* address rises by sizeof(int) = 4, now &a[1] */
printf("%d\n", *p);            /* 20 */
printf("%d\n", *(p + 2));      /* 40 : a[3] */
int *q = &a[4];
printf("%d\n", (int)(q - p));  /* 3 elements apart, not 12 bytes */
printf("%d\n", q > p);         /* 1 : q is further along the array */
double d[3]; double *pd = d;
pd += 2;                       /* moves 16 bytes, to &d[2] */

#include <stdio.h>
int main(void) {
    int a[5] = {10, 20, 30, 40, 50};
    int *p = a, *q = a + 4;
    double d[3], *r = d;
    p += 2;
    printf("%d %td\n", *p, q - p);
    printf("%td %td\n", (char *)q - (char *)p, (char *)(r + 2) - (char *)r);
    int x = *p++;
    printf("%d %d %d\n", x, *p, p < q);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int grow(int **pa, size_t n) {
    int *t = realloc(*pa, n * sizeof **pa);
    if (t != NULL) *pa = t;          /* on failure *pa keeps the old block */
    return t != NULL;
}
int main(void) {
    int *a = calloc(2, sizeof *a);   /* {0, 0} */
    if (a == NULL || !grow(&a, 4)) { free(a); return 1; }
    a[1] = 7;  a[2] = a[1] * 2;  a[3] = a[0] + 1;
    printf("%d %d %d %d\n", a[0], a[1], a[2], a[3]);
    free(a);
    return 0;
}

