void swap(int *x, int *y) { int t = *x; *x = *y; *y = t; }
void doubleAll(int arr[], int n) {         /* arr is really int *arr */
    for (int i = 0; i < n; i++) arr[i] *= 2;   /* caller's array changes */
}
int main(void) {
    int a = 1, b = 2, v[3] = {1, 2, 3};
    swap(&a, &b);                /* pass ADDRESSES: a = 2, b = 1 */
    doubleAll(v, 3);             /* array name is already an address */
    printf("%d %d %d\n", a, b, v[2]);  /* 2 1 6 */
    return 0;
}

int add(int a, int b) { return a + b; }
int cmp(const void *x, const void *y) { return *(int *)x - *(int *)y; }
int (*fp)(int, int) = add;            /* function pointer */
printf("%d\n", fp(2, 3));             /* 5 ; (*fp)(2, 3) also works */
int v[] = {3, 1, 2};
qsort(v, 3, sizeof(int), cmp);        /* cmp passed as a callback */
char *s = "abc";                      /* points to a read-only literal */
while (*s) putchar(*s++);             /* prints abc; s ends at '\0' */
char t[] = "abc";  t[0] = 'x';        /* array copy: writable, "xbc" */

#include <stdio.h>
int sq(int x) { return x * x; }
int neg(int x) { return -x; }
void apply(int *a, int n, int (*f)(int)) {
    for (int *p = a; p < a + n; p++)
        *p = f(*p);
}
int main(void) {
    int v[4] = {1, -2, 3, -4};
    apply(v, 4, sq);
    apply(v + 2, 2, neg);
