struct Student {
    int roll;
    char name[20];
    float marks;
};                                        /* the semicolon is required */
struct Student s1 = {1, "Ram", 78.5};     /* positional initialisation */
struct Student s2 = {.roll = 2, .name = "Sita"};  /* C99; marks becomes 0 */
struct Student s3;
s3 = s1;                                  /* member-wise copy is allowed */
s3.marks = 80;                            /* dot operator */
strcpy(s3.name, "Shyam");                 /* arrays need strcpy, not = */
printf("%s %.1f\n", s3.name, s3.marks);   /* Shyam 80.0 */

typedef struct { int day, month, year; } Date;   /* alias, no tag needed */
typedef struct {
    char name[20];
    Date dob;                       /* nested structure */
} Person;
Person p = {"Hari", {15, 3, 2000}}; /* nested braces */
printf("%d\n", p.dob.year);         /* 2000 : chain the dots */
printf("%zu\n", sizeof(Date));      /* 12 : three ints, no padding */
typedef unsigned long ulong;        /* typedef works for any type */

union Data { int i; float f; char c[4]; };
union Data d;
printf("%zu\n", sizeof(d));    /* 4 : the largest member, shared */
d.i = 65;
printf("%c\n", d.c[0]);        /* 'A' on a little-endian machine: bytes overlap */
d.f = 1.5f;                    /* overwrites i and c */
printf("%d\n", d.i);           /* bit pattern of 1.5, NOT 65 */
union { int i; double x; } u;  /* sizeof u = 8 */
union Data e = {7};            /* only the first member can be initialised */

enum Day { SUN, MON, TUE = 5, WED };   /* 0, 1, 5, 6 */
enum Day d = WED;
printf("%d\n", d);                     /* 6 */
struct Flags {
    unsigned int ready : 1;            /* 1 bit : 0 or 1 */
    unsigned int mode  : 3;            /* 3 bits: 0..7 */
    unsigned int level : 4;            /* 4 bits: 0..15 */
};                                     /* all 8 bits fit in one 4-byte unsigned */
struct Flags f = {1, 7, 9};
printf("%zu %u\n", sizeof(f), f.mode); /* 4 7 */
f.mode = 9;                            /* overflow: stores 9 & 7 = 1 */

#include <stdio.h>
#include <stddef.h>
struct Rec  { char tag; double val; short id; };
struct Rec2 { double val; short id; char tag; };
int main(void) {
    printf("%zu %zu %zu\n", offsetof(struct Rec, val),
           offsetof(struct Rec, id), sizeof(struct Rec));
    printf("%zu %zu\n", offsetof(struct Rec2, tag), sizeof(struct Rec2));
    return 0;
}

#include <stdio.h>
enum Kind { INT, REAL };
struct Val {
    enum Kind k;
    union { int i; double d; } u;   /* one of the two at a time */
};
void show(struct Val v) {
    if (v.k == INT) printf("int %d\n", v.u.i);
    else            printf("real %.2f\n", v.u.d);
}
int main(void) {
    struct Val a = {INT, {.i = 42}}, b = {REAL, {.d = 0.5}};
    show(a); show(b); printf("%zu\n", sizeof(struct Val));
    return 0;
}

