struct Student { int roll; char name[20]; float marks; };
struct Student s[3] = {{1, "Ram", 70}, {2, "Sita", 90}, {3, "Hari", 80}};
/* selection-style sort by marks, descending: swap whole records */
for (int i = 0; i < 2; i++)
    for (int j = i + 1; j < 3; j++)
        if (s[j].marks > s[i].marks) {
            struct Student t = s[i]; s[i] = s[j]; s[j] = t;
        }
for (int i = 0; i < 3; i++)
    printf("%d %s %.0f\n", s[i].roll, s[i].name, s[i].marks);
/* 2 Sita 90  /  3 Hari 80  /  1 Ram 70 */

struct Point { int x, y; };
struct Point pt = {3, 4}, *p = &pt;
printf("%d\n", p->x);                  /* 3 */
printf("%d\n", (*p).y);                /* 4 : same as p->y */
p->x = 10;                             /* modifies pt.x through the pointer */
printf("%d\n", pt.x);                  /* 10 */
struct Point arr[2] = {{1, 2}, {5, 6}};
struct Point *q = arr;
q++;                                   /* advances sizeof(struct Point) = 8 bytes */
printf("%d %d\n", q->x, (q - 1)->y);   /* 5 2 */

struct Point { int x, y; };
void byValue(struct Point p)   { p.x = 100; }      /* copy: caller unchanged */
void byPointer(struct Point *p) { p->x = 100; }    /* caller's record modified */
void show(const struct Point *p) { printf("%d %d\n", p->x, p->y); }
struct Point makePoint(int x, int y) { struct Point t = {x, y}; return t; }
int main(void) {
    struct Point a = makePoint(1, 2);    /* structure returned by value */
    byValue(a);    show(&a);             /* 1 2 */
    byPointer(&a); show(&a);             /* 100 2 */
    return 0;
}

struct Node { int data; struct Node *next; };   /* self-referential */
struct Node *head = NULL;
for (int i = 3; i >= 1; i--) {                 /* insert at the front */
    struct Node *n = malloc(sizeof(struct Node));
    n->data = i;  n->next = head;  head = n;
}
for (struct Node *p = head; p != NULL; p = p->next)
    printf("%d ", p->data);                    /* 1 2 3 */
/* dynamic array of records, size known only at run time */
struct Student *st = malloc(5 * sizeof(struct Student));
st[2].roll = 7;   (st + 2)->marks = 88.0f;     /* both forms address record 2 */

struct Student { int roll; char name[20]; float marks; };
struct Student *topper(struct Student *s, int n) {   /* returns a pointer */
    struct Student *best = s;
    for (int i = 1; i < n; i++)
        if (s[i].marks > best->marks) best = &s[i];
    return best;               /* points into the caller's array: not dangling */
}
int main(void) {
    int n;  scanf("%d", &n);
    struct Student *s = malloc(n * sizeof *s);       /* n records on the heap */
    for (int i = 0; i < n; i++)                      /* name is an array: no & */
        scanf("%d %s %f", &s[i].roll, s[i].name, &s[i].marks);
    printf("Topper: %s\n", topper(s, n)->name);
    free(s);  return 0;
}

#include <stdio.h>
struct St { char name[8]; int marks; };
int main(void) {
    struct St s[4] = {{"Asha", 72}, {"Bina", 65}, {"Chet", 72}, {"Dev", 90}};
    for (int i = 1; i < 4; i++) {           /* insertion sort, descending */
        struct St key = s[i];
        int j = i - 1;
        while (j >= 0 && s[j].marks < key.marks) { s[j + 1] = s[j]; j--; }
        s[j + 1] = key;
    }
    for (int i = 0; i < 4; i++) printf("%s %d\n", s[i].name, s[i].marks);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
struct Node { int d; struct Node *next; };
int main(void) {
    struct Node *head = NULL, **tail = &head;
    for (int i = 1; i <= 3; i++) {                /* append at the end */
        struct Node *n = malloc(sizeof *n);
        n->d = i * 10; n->next = NULL;
        *tail = n; tail = &n->next;
    }
    for (struct Node *p = head; p; p = p->next) printf("%d ", p->d);
    while (head) { struct Node *t = head->next; free(head); head = t; }
    printf("\n%s\n", head == NULL ? "freed" : "leak");
    return 0;
}

