fclose(fp);                               /* flush buffer, release handle */

FILE *in = fopen("a.txt", "r"), *out = fopen("b.txt", "w");
int ch;                                   /* int, not char, to hold EOF */
if (in == NULL || out == NULL) return 1;
while ((ch = fgetc(in)) != EOF)           /* copy a file character by character */
    fputc(ch, out);
fclose(in);
fclose(out);

char line[100];
FILE *fp = fopen("data.txt", "r");
while (fgets(line, sizeof line, fp) != NULL)    /* line by line */
    printf("%s", line);                         /* '\n' is already inside */
rewind(fp);                                     /* back to the beginning */
int roll;  char name[20];
while (fscanf(fp, "%d %s", &roll, name) == 2)   /* field by field */
    printf("%d-%s\n", roll, name);
fclose(fp);

struct Student { int roll; char name[20]; float marks; } s = {1, "Ram", 70};
FILE *fp = fopen("stu.dat", "ab");              /* append a record */
fwrite(&s, sizeof(struct Student), 1, fp);
fclose(fp);
fp = fopen("stu.dat", "rb");
int n = 2;                                      /* read the n-th record (0-based) */
fseek(fp, n * sizeof(struct Student), SEEK_SET);
if (fread(&s, sizeof s, 1, fp) == 1)            /* 1 item read successfully */
    printf("%d %s\n", s.roll, s.name);
fclose(fp);

FILE *fp = fopen("stu.dat", "r+b");             /* read and write, binary */
fseek(fp, 0L, SEEK_END);
long size = ftell(fp);                          /* bytes in the file */
long count = size / sizeof(struct Student);     /* number of records */
fseek(fp, -1L * sizeof(struct Student), SEEK_END); /* last record */
fread(&s, sizeof s, 1, fp);
s.marks = 95;
fseek(fp, -1L * sizeof(struct Student), SEEK_CUR); /* back over what we read */
fwrite(&s, sizeof s, 1, fp);                    /* update in place */
rewind(fp);                                     /* position 0, flags cleared */
fclose(fp);

