    fwrite(a, sizeof(int), 4, fp);
    fseek(fp, -2L * (long)sizeof(int), SEEK_END);
    fread(&x, sizeof x, 1, fp);
    fseek(fp, 0L, SEEK_CUR);
    fwrite(&x, sizeof x, 1, fp);
    rewind(fp);
    fread(a, sizeof(int), 4, fp);
    printf("x=%d pos=%ld last=%d\n", x, ftell(fp), a[3]);
    fclose(fp);
    return 0;
}

